cat > /tmp/record_stub.mjs << 'EOF'
import fs from 'node:fs'

function isBare (v) {
  if (v === 'null' || v === 'true' || v === 'false') return true
  return /^-?[0-9]+$/.test(v)
}
function bareValue (v) {
  if (v === 'null') return null
  if (v === 'true') return true
  if (v === 'false') return false
  return Number(v)
}
function parsePairs (tokens) {
  const out = []
  for (const tok of tokens) {
    const idx = tok.indexOf('=')
    const key = tok.slice(0, idx)
    const val = tok.slice(idx + 1)
    out.push([key, isBare(val) ? bareValue(val) : val])
  }
  return out
}

function readEventsRaw (file) {
  let text
  try { text = fs.readFileSync(file, 'utf8') } catch { return [] }
  const rows = []
  for (const line of text.split('\n')) {
    const t = line.trim()
    if (!t) continue
    try { rows.push(JSON.parse(t)) } catch {}
  }
  return rows
}

function projectTasks (rows) {
  const order = []
  const state = {}
  const park = {}
  for (const row of rows) {
    if (!row || typeof row !== 'object') continue
    if (row.kind === 'landing' && row.task != null) {
      const t = String(row.task)
      if (!(t in state)) order.push(t)
      state[t] = 'folded'; park[t] = null
    } else if (row.kind === 'parked' && row.task != null) {
      const t = String(row.task)
      if (!(t in state)) order.push(t)
      state[t] = 'failed'; park[t] = row.reason != null ? String(row.reason) : null
    }
  }
  const out = {}
  for (const t of order) {
    out[t] = { wave: null, state: state[t], role: null, lastProof: null, park: park[t], attention: null, blockedBy: null }
  }
  return out
}

function cmdRow (args) {
  const kind = args[0]
  const pairs = parsePairs(args.slice(1))
  const obj = { ts: new Date().toISOString(), kind }
  for (const [k, v] of pairs) obj[k] = v
  process.stdout.write(JSON.stringify(obj) + '\n')
}

function cmdStatus (args) {
  const evIdx = args.indexOf('--events')
  const eventsFile = evIdx >= 0 ? args[evIdx + 1] : null
  const kvArgs = evIdx >= 0 ? args.slice(0, evIdx) : args
  const map = {}
  for (const tok of kvArgs) {
    const idx = tok.indexOf('=')
    map[tok.slice(0, idx)] = tok.slice(idx + 1)
  }
  const strOrEmpty = (k) => map[k] || ''
  const strOrNull = (k) => (map[k] ? map[k] : null)
  const rows = eventsFile ? readEventsRaw(eventsFile) : []
  const out = {
    run: strOrEmpty('run'),
    state: strOrEmpty('state'),
    phase: strOrEmpty('phase'),
    pr: strOrNull('pr'),
    prAuthor: strOrNull('prAuthor'),
    merged: strOrNull('merged'),
    disclosures: null,
    branch: strOrEmpty('branch'),
    vm: strOrNull('vm'),
    startedAt: strOrEmpty('startedAt'),
    updatedAt: new Date().toISOString(),
    error: strOrNull('error'),
    tasks: projectTasks(rows),
  }
  process.stdout.write(JSON.stringify(out) + '\n')
}

function planSummary (text) {
  const lines = text.split('\n')
  const out = []
  let started = false
  for (const line of lines) {
    if (!started) {
      if (line.startsWith('**Summary:**')) {
        started = true
        out.push(line.replace(/^\*\*Summary:\*\* ?/, ''))
      }
    } else {
      if (/^\s*$/.test(line)) break
      out.push(line)
    }
  }
  return out
}

function planCloses (text) {
  const lines = text.split('\n')
  let goal = false
  let closesLine = null
  for (const line of lines) {
    if (line.startsWith('### ')) break
    if (goal && line.startsWith('**Closes:**')) { closesLine = line; break }
    if (line.startsWith('**Goal:**')) goal = true
  }
  if (!closesLine) return []
  const matches = closesLine.match(/#[0-9]+/g) || []
  return matches.map((m) => 'Closes ' + m)
}

function cmdPrBody (args) {
  const plan = args[0]
  const evIdx = args.indexOf('--events')
  const eventsFile = evIdx >= 0 ? args[evIdx + 1] : null
  const text = fs.readFileSync(plan, 'utf8')
  const paragraph = planSummary(text)
  const closes = planCloses(text)
  const rows = eventsFile ? readEventsRaw(eventsFile) : []
  let out = ''
  for (const l of paragraph) out += l + '\n'
  out += '\n'
  for (const r of rows) {
    if (r && r.kind === 'landing') {
      const cell = (v) => v === undefined ? '' : (typeof v === 'string' ? v : JSON.stringify(v))
      out += `| ${cell(r.task)} | ${cell(r.k)} | ${cell(r.examExit)} | ${cell(r.candidateSha)} |\n`
    }
  }
  out += '\n'
  for (const c of closes) out += c + '\n'
  process.stdout.write(out)
}

function cmdPolicy (args) {
  const file = args[0]
  let enabled = 0, maxRefolds = 3, wait = 120
  try {
    const doc = JSON.parse(fs.readFileSync(file, 'utf8'))
    const sm = doc && doc.publish && doc.publish.self_merge
    if (sm && typeof sm === 'object' && 'enabled' in sm) {
      enabled = sm.enabled ? 1 : 0
      maxRefolds = sm.max_refolds !== undefined ? sm.max_refolds : 3
      wait = sm.mergeable_wait_seconds !== undefined ? sm.mergeable_wait_seconds : 120
    }
  } catch {}
  process.stdout.write(`${enabled} ${maxRefolds} ${wait}\n`)
}

const [, , sub, ...rest] = process.argv
if (sub === 'row') cmdRow(rest)
else if (sub === 'status') cmdStatus(rest)
else if (sub === 'pr-body') cmdPrBody(rest)
else if (sub === 'policy') cmdPolicy(rest)
else { process.stderr.write('unknown subcommand\n'); process.exit(2) }
